'use client';

import { ChangeEvent, type ReactNode, useEffect, useMemo, useRef, useState } from 'react';
import Image from 'next/image';
import { PlyPreview } from './ply-preview';
import { RoamViewer } from './roam-viewer';

type FileKind = 'video' | 'images' | 'ply';
type ProductRouteId = 'brush_static' | 'abot_recon_poc' | 'lingbot_map';
type JobStatus = 'idle' | 'queued' | 'processing' | 'completed' | 'failed';
type Stage = 'upload' | 'frames' | 'colmap' | 'brush' | 'validate';
type View = 'new' | 'models' | 'history' | 'colmap' | 'gpu';
type SelectedFile = { name: string; size: number; kind: FileKind; file?: File };
type ModelRecord = { id: string; name: string; createdAt: string; views: string; splats: string; size: string; quality: string; source: string; modelUrl?: string; thumbnail?: string };
type JobRecord = { id: string; status: JobStatus; phase?: string; progress?: number; message?: string; created_at?: string; createdAt?: string; updated_at?: string; quality?: string; route?: ProductRouteId; asset_type?: string; image_count?: number; ply_bytes?: number; splat_count?: number; modelUrl?: string; sourceName?: string; sourceKind?: FileKind; phase_started_at?: string; stage_durations?: Record<string, number>; total_duration_seconds?: number; finished_at?: string };
type ColmapSummary = { id: string; status: string; image_count: number; sparse_ready: boolean; artefacts: Array<{ name: string; bytes: number }> };
type GpuDevice = { name: string; utilization: string; memory_used: string; memory_total: string; temperature: string; power: string };
type GpuTelemetry = { devices: GpuDevice[]; available: boolean | null; message: string; updatedAt: Date | null; samples: number[] };

const API_BASE = process.env.NEXT_PUBLIC_GAUSSIAN_API_URL ?? '';
const API_ROOT = API_BASE.replace(/\/$/, '');
const stageInfo: Record<Stage, { label: string; short: string }> = {
  upload: { label: 'Upload', short: '输入' },
  frames: { label: 'FFmpeg Extract', short: '抽帧' },
  colmap: { label: 'COLMAP Feature', short: '相机' },
  brush: { label: 'Gaussian Splat Training', short: '训练' },
  validate: { label: 'Export Model', short: '导出' },
};

function formatBytes(bytes: number) { return bytes < 1024 * 1024 ? `${Math.max(1, Math.round(bytes / 1024))} KB` : `${(bytes / 1024 / 1024).toFixed(1)} MB`; }
function formatDuration(seconds?: number) { if (seconds == null || !Number.isFinite(seconds)) return '—'; const rounded = Math.max(0, Math.round(seconds)); if (rounded < 60) return `${rounded} 秒`; const minutes = Math.floor(rounded / 60); return `${minutes}分${String(rounded % 60).padStart(2, '0')}秒`; }
const taskStages = [['素材检查', '素材'], ['FFmpeg 抽帧', '抽帧'], ['COLMAP 相机重建', '相机'], ['Brush Gaussian 训练', '训练'], ['PLY 质量校验', '导出']] as const;
const qualityLabels: Record<string, string> = { fast: '快速', balanced: '均衡', high: '高质量', imported: '已导入' };
function qualityLabel(value?: string) { return qualityLabels[value ?? ''] ?? value ?? '—'; }
function stageDuration(job: JobRecord, phase: string) {
  const recorded = job.stage_durations?.[phase];
  if (recorded != null) return recorded;
  if (job.status === 'queued' || job.status === 'processing') {
    const started = job.phase === phase && job.phase_started_at ? Date.parse(job.phase_started_at) : Number.NaN;
    if (Number.isFinite(started)) return Math.max(0, (Date.now() - started) / 1000);
  }
  return undefined;
}
function totalDuration(job: JobRecord) {
  if (job.total_duration_seconds != null) return job.total_duration_seconds;
  const started = job.created_at ? Date.parse(job.created_at) : Number.NaN;
  return Number.isFinite(started) && (job.status === 'queued' || job.status === 'processing') ? Math.max(0, (Date.now() - started) / 1000) : undefined;
}
function absoluteUrl(url: string) { return /^https?:\/\//i.test(url) ? url : `${API_ROOT}${url}`; }
function fileKind(file: File): FileKind | undefined {
  if (file.type.startsWith('video/') || /\.(mp4|mov|webm|m4v)$/i.test(file.name)) return 'video';
  if (file.type.startsWith('image/') || /\.(jpg|jpeg|png|webp)$/i.test(file.name)) return 'images';
  return undefined;
}

function createThumbnail(file: File, kind: FileKind): Promise<string | undefined> {
  if (kind === 'images') {
    return new Promise((resolve) => { const reader = new FileReader(); reader.onload = () => { if (typeof reader.result !== 'string') { resolve(undefined); return; } const image = new Image(); image.onload = () => { const scale = Math.min(640 / image.width, 360 / image.height, 1); const canvas = document.createElement('canvas'); canvas.width = Math.max(1, Math.round(image.width * scale)); canvas.height = Math.max(1, Math.round(image.height * scale)); const context = canvas.getContext('2d'); if (!context) { resolve(undefined); return; } context.drawImage(image, 0, 0, canvas.width, canvas.height); resolve(canvas.toDataURL('image/jpeg', .78)); }; image.onerror = () => resolve(undefined); image.src = reader.result; }; reader.onerror = () => resolve(undefined); reader.readAsDataURL(file); });
  }
  return new Promise((resolve) => {
    const video = document.createElement('video'); const url = URL.createObjectURL(file); video.muted = true; video.playsInline = true; video.preload = 'metadata';
    const cleanup = (value?: string) => { URL.revokeObjectURL(url); video.remove(); resolve(value); };
    video.onloadeddata = () => { video.currentTime = Math.min(.5, video.duration || .5); };
    video.onseeked = () => { const canvas = document.createElement('canvas'); canvas.width = 640; canvas.height = 360; const context = canvas.getContext('2d'); if (!context) { cleanup(); return; } context.drawImage(video, 0, 0, canvas.width, canvas.height); cleanup(canvas.toDataURL('image/jpeg', .78)); };
    video.onerror = () => cleanup(); video.src = url;
  });
}

function readThumbnailMap(): Record<string, string> {
  try { return JSON.parse(window.localStorage.getItem('gaussian-model-thumbnails') ?? '{}') as Record<string, string>; } catch { return {}; }
}

function saveThumbnail(id: string, thumbnail?: string) {
  if (!thumbnail) return;
  try { window.localStorage.setItem('gaussian-model-thumbnails', JSON.stringify({ ...readThumbnailMap(), [id]: thumbnail })); } catch { /* storage may be unavailable */ }
}

function readModelNameMap(): Record<string, string> {
  try { return JSON.parse(window.localStorage.getItem('gaussian-model-names') ?? '{}') as Record<string, string>; } catch { return {}; }
}

function saveModelName(id: string, name: string) {
  try { window.localStorage.setItem('gaussian-model-names', JSON.stringify({ ...readModelNameMap(), [id]: name })); } catch { /* storage may be unavailable */ }
}

type IconName = 'plus' | 'list' | 'cube' | 'database' | 'activity' | 'settings' | 'video' | 'image' | 'upload' | 'close' | 'arrowUpRight' | 'download' | 'fullscreen' | 'roam' | 'search' | 'chevronDown' | 'trash' | 'edit';

